"use client";

import { useRef, useState } from "react";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  type AlertDialogMotion,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

/** 确认框的动效预设，透传给 `AlertDialog`（ADR 0021）。缺省 `pop`。 */
type UnsavedChangesDialogMotion = AlertDialogMotion;

type UnsavedChangesDialogProps = {
  open: boolean;
  /** 用户选择放弃修改：关闭浮层或继续跳转。 */
  onConfirm: () => void;
  /** 用户选择继续编辑（含 Esc、点遮罩）。 */
  onCancel: () => void;
  title?: string;
  description?: string;
  confirmLabel?: string;
  /** 动效预设，不写就用 `AlertDialog` 的缺省 `pop`。 */
  motion?: UnsavedChangesDialogMotion;
};

/**
 * 有未保存修改时离开前的确认框。打开时焦点在「继续编辑」上；确认按钮是 `destructive`。
 * 浮层关闭由 `useUnsavedCloseGuard` 驱动，整页跳转由表单模板的离开拦截驱动。
 */
function UnsavedChangesDialog({
  open,
  onConfirm,
  onCancel,
  title = "放弃未保存的修改？",
  description = "离开后，这次填写的内容不会保存。",
  confirmLabel = "放弃修改",
  motion,
}: UnsavedChangesDialogProps) {
  const cancelRef = useRef<HTMLButtonElement>(null);
  return (
    <AlertDialog
      motion={motion}
      open={open}
      onOpenChange={(next) => {
        if (!next) onCancel();
      }}
    >
      <AlertDialogContent initialFocus={cancelRef}>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel ref={cancelRef}>继续编辑</AlertDialogCancel>
          <AlertDialogAction variant="destructive" onClick={onConfirm}>
            {confirmLabel}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

/**
 * 浮层（对话框、抽屉）的关闭守卫。把 `handleOpenChange` 交给浮层的 `onOpenChange`，
 * 把 `dialogProps` 展开到 `UnsavedChangesDialog` 上。
 * - 脏时关闭请求先弹确认框，确认后才调用 `onClose`；不脏时直接关闭。
 * - `pending` 为真时忽略一切关闭请求（Esc、点遮罩、取消、关闭图标）。
 * - 提交成功后直接调用 `onClose`，不经过守卫。
 */
function useUnsavedCloseGuard({
  dirty,
  pending = false,
  onClose,
}: {
  dirty: boolean;
  pending?: boolean;
  onClose: () => void;
}) {
  const [confirming, setConfirming] = useState(false);

  const requestClose = () => {
    if (pending) return;
    if (dirty) setConfirming(true);
    else onClose();
  };

  return {
    /** 传给浮层根的 `onOpenChange`。打开请求不处理。 */
    handleOpenChange: (open: boolean) => {
      if (!open) requestClose();
    },
    /** 自定义的关闭入口（如页脚的「取消」不是 `DialogClose` 时）。 */
    requestClose,
    dialogProps: {
      open: confirming,
      onConfirm: () => {
        setConfirming(false);
        onClose();
      },
      onCancel: () => setConfirming(false),
    },
  };
}

export type { UnsavedChangesDialogMotion, UnsavedChangesDialogProps };
export { UnsavedChangesDialog, useUnsavedCloseGuard };
